mapper.delete:
DELETE FROM repository_markdown_sources WHERE repo_id=#{repositoryId}

    AND file_path NOT IN

        #{path}

mapper.select:
SELECT ,s.content
FROM repository_markdown_sources s

WHERE s.repo_id=#{repositoryId} AND s.snapshot_id=#{snapshotId} AND s.file_path=#{filePath}

SELECT id FROM code_chunks
WHERE repo_id=#{repositoryId} AND snapshot_id=#{snapshotId} AND file_path=#{filePath}
ORDER BY start_line NULLS FIRST,id
LIMIT #{limit}
